<script setup lang="ts">
import { positions, labels } from '#shared/domain'
const route = useRoute(); const proposalId = String(route.params.id)
const { data, error: fetchError, refresh } = await useFetch<any>(`/api/proposals/${proposalId}`)
const tab = ref('conversation'); const busy = ref(false); const error = ref(''); const notice = ref(''); const outcome = ref(''); const status = ref('Agreed')
const form = reactive({name:'',position:'APPROVE',justification:'',amendment:{title:'',description:'',deadline:''}})
const responseClass = (position: string) => 'position-' + position.toLowerCase().replaceAll(' ', '-')
const symbols: Record<string,string> = { APPROVE:'✓', 'EXPRESS CONCERN':'!', 'ASK CLARIFYING QUESTION':'?', COMMENT:'↳', 'SUGGEST MODIFICATION':'↻', 'STAND ASIDE':'○', BLOCK:'×' }
const current = computed(() => (data.value?.responses || []).filter((r:any)=>r.revision===data.value?.proposal?.revision))
const stances = computed(() => current.value.filter((r:any)=>!['COMMENT','ASK CLARIFYING QUESTION','SUGGEST MODIFICATION'].includes(r.position)))
const expired = ref(false)
function updateClock() { expired.value = !!data.value?.proposal && Date.now() >= Date.parse(data.value.proposal.deadline) }
let timer: ReturnType<typeof setInterval> | undefined
onMounted(() => { form.name=localStorage.getItem('consensish-name') || ''; updateClock(); timer=setInterval(updateClock,15000) })
onUnmounted(() => clearInterval(timer))
watch(() => data.value?.proposal?.deadline, updateClock)
const open = computed(() => data.value?.proposal?.status==='Review' && !expired.value)
async function action(path:string, body:any) { busy.value=true; error.value=''; try { await $fetch(`/api/proposals/${proposalId}/${path}`, {method:'POST',body}); await refresh(); updateClock(); return true } catch(e:any) { error.value=e.data?.statusMessage || 'Something went wrong. Please try again.'; return false } finally { busy.value=false } }
async function respond() { const body = { ...form, amendment: { ...form.amendment, deadline: form.amendment.deadline ? new Date(form.amendment.deadline).toISOString() : '' } }; if (await action('responses',body)) { localStorage.setItem('consensish-name',form.name); notice.value='Your response is saved. You can update your position while the review is open.'; form.justification='' } }
async function amend(responseId:string, accept:boolean) { if(await action('amend',{responseId,accept})) notice.value=accept?'Modification accepted. A fresh review is open.':'Modification declined.' }
async function copy() { try { await navigator.clipboard.writeText(location.href); notice.value='Decision link copied. Share the password separately if you set one.' } catch { notice.value='Copy the decision URL from your address bar.' } }
function date(s:string) { return new Date(s).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}) }
function beginModification() { if(form.position==='SUGGEST MODIFICATION' && !form.amendment.title) { form.amendment.title=data.value.proposal.title; form.amendment.description=data.value.proposal.description } }
</script>
<template><UnlockGate v-if="data?.locked" :endpoint="`/api/proposals/${proposalId}/unlock`" label="decision" @unlocked="refresh" /><main v-else-if="data?.proposal" class="workspace"><NuxtLink :to="`/g/${data.group.id}`" class="breadcrumb">← {{ data.group.name }}</NuxtLink><div class="workspace-head"><div><div class="eyebrow">{{ data.proposal.program || data.proposal.type }} <span> / REVISION {{ data.proposal.revision }}</span></div><h1 class="medium">{{ data.proposal.title }}</h1><p>Proposed by {{ data.proposal.facilitator }} · {{ date(data.proposal.createdAt) }}</p></div><button class="button secondary" @click="copy">↗ Share decision</button></div><p v-if="notice" class="notice" role="status">{{ notice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><div class="decision-layout"><div><section class="panel proposal-body"><div class="section-head"><span class="badge" :class="{review:data.proposal.status==='Review',agreed:data.proposal.status==='Agreed'}">{{ data.proposal.status==='Review' ? expired ? 'Awaiting facilitator outcome' : 'Open for review' : data.proposal.status }}</span><span class="muted">{{ data.proposal.locked ? 'Password protected' : 'Anyone with the link' }}</span></div><h2>The proposal</h2><p class="prewrap">{{ data.proposal.description }}</p><div class="proposal-facts"><div><small>SETUP BUDGET</small><strong>{{ new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(data.proposal.budget) }}</strong></div><div><small>RECURRING COSTS</small><strong>{{ data.proposal.recurring || 'None specified' }}</strong></div><div><small>REVIEW DEADLINE</small><strong>{{ date(data.proposal.deadline) }}</strong></div></div><template v-for="[title,value] in [['Implementation timeline',data.proposal.timeline],['Evidence & resources',data.proposal.evidence],['Meeting',data.proposal.meeting]]" :key="title"><template v-if="value"><h3>{{ title }}</h3><p class="prewrap">{{ value }}</p></template></template><div v-if="data.proposal.outcome" class="notice"><strong>{{ data.proposal.status }}</strong><p class="prewrap">{{ data.proposal.outcome }}</p></div></section><nav class="tabs" aria-label="Decision views"><button :class="{active:tab==='conversation'}" @click="tab='conversation'">Conversation <span>{{ current.length }}</span></button><button :class="{active:tab==='history'}" @click="tab='history'">Decision history</button></nav><section v-if="tab==='conversation'" class="conversation"><div v-if="!current.length" class="empty compact"><h2>No responses yet</h2><p>Use the response form to state a position, ask a question, comment, or suggest a change.</p></div><article v-for="r in [...current].reverse()" :key="r.id" class="response"><span class="avatar" :class="responseClass(r.position)">{{ symbols[r.position] }}</span><div class="response-content"><div class="section-head"><strong>{{ r.name }} <small v-if="r.participantId===data.participantId">(you)</small></strong><time>{{ date(r.createdAt) }}</time></div><span class="response-position" :class="responseClass(r.position)">{{ labels[r.position as keyof typeof labels] }}</span><p v-if="r.justification" class="prewrap">{{ r.justification }}</p><div v-if="r.amendment" class="amendment"><strong>{{ r.amendment.title }}</strong><p class="prewrap">{{ r.amendment.description }}</p><p v-if="r.amendment.deadline">Proposed deadline: {{ date(r.amendment.deadline) }}</p><template v-if="data.isAdmin && !r.resolved && data.proposal.status==='Review'"><p class="hint">Accept only with all proposers’ consent. Acceptance clears current positions and asks everyone to respond again.</p><div class="actions"><button class="button" :disabled="busy" @click="amend(r.id,true)">Confirm consent & accept</button><button class="button secondary" :disabled="busy" @click="amend(r.id,false)">Decline</button></div></template><small v-else-if="r.resolved">Reviewed by facilitator</small></div></div></article></section><section v-else class="panel timeline"><div v-for="a in data.activity" :key="a.id" class="event"><span class="event-dot"/><div><time>{{ date(a.createdAt) }}</time><p>{{ a.text }}</p></div></div><details v-for="rev in data.revisions" :key="rev.id"><summary>Revision {{ rev.revision }} · {{ rev.title }}</summary><p class="prewrap">{{ rev.description }}</p><p v-for="r in data.responses.filter((r:any)=>r.revision===rev.revision)" :key="r.id"><strong>{{ r.name }} · {{ r.position }}</strong><br>{{ r.justification }}</p></details></section></div><aside><section class="panel pulse"><div class="eyebrow">CURRENT POSITIONS</div><h2>{{ stances.length }} <span>positions recorded</span></h2><div v-for="position in ['APPROVE','EXPRESS CONCERN','STAND ASIDE','BLOCK']" :key="position" class="tally"><span :class="responseClass(position)">{{ symbols[position] }} &nbsp;{{ labels[position as keyof typeof labels] }}</span><strong>{{ stances.filter((r:any)=>r.position===position).length }}</strong></div><p class="hint">No response means stand aside by default. These counts show explicit responses only. Agreement is recorded by the facilitator after review.</p><button class="subtle" @click="refresh()">Refresh responses ↻</button></section><section v-if="open" class="panel response-form"><h2>Respond</h2><form @submit.prevent="respond"><label>Your name<input v-model="form.name" required maxlength="80" autocomplete="name"></label><label>Your response<select v-model="form.position" :class="responseClass(form.position)" @change="beginModification"><option v-for="p in positions" :key="p" :value="p">{{ symbols[p] }} {{ labels[p] }}</option></select></label><label>{{ form.position==='ASK CLARIFYING QUESTION'?'Your question':'Comment or reason' }}<small v-if="['APPROVE','STAND ASIDE'].includes(form.position)">optional</small><textarea v-model="form.justification" :required="!['APPROVE','STAND ASIDE'].includes(form.position)" maxlength="5000" rows="4" /></label><template v-if="form.position==='SUGGEST MODIFICATION'"><label>Revised title<input v-model="form.amendment.title" required maxlength="160"></label><label>Revised proposal<textarea v-model="form.amendment.description" required maxlength="10000" rows="6" /></label><label>Extend deadline <small>optional</small><input v-model="form.amendment.deadline" type="datetime-local"><span class="hint">Leave blank for a new full review window.</span></label></template><button class="button full" :disabled="busy">{{ busy?'Saving…':'Save response' }}</button><p class="hint">Your browser remembers your position. Names are self-declared. Comments, questions, and suggestions keep your existing position.</p></form></section><section v-else class="panel"><h2>{{ data.proposal.status==='Review'?'Review ended':'Decision recorded' }}</h2><p>{{ data.proposal.status==='Review'?'The review window has ended. Your facilitator will record the outcome.':'The outcome and previous responses are available in the decision history.' }}</p></section><details v-if="data.isAdmin && data.proposal.status==='Review'" class="panel"><summary>Facilitator controls</summary><p class="hint">Record an outcome after the review window, or withdraw the proposal. Blocks prevent agreement.</p><form @submit.prevent="action('close',{status,outcome})"><label>Outcome<select v-model="status"><option>Agreed</option><option>Not agreed</option><option>Withdrawn</option></select></label><label>Decision & rationale<textarea v-model="outcome" required maxlength="5000" rows="4" /></label><button class="button" :disabled="busy">Record outcome</button></form></details></aside></div></main><main v-else class="narrow"><h1 class="medium">{{ fetchError?.statusCode===404?'Decision not found.':'Could not load this decision.' }}</h1><p>Check the link shared by your group.</p><button class="button" @click="refresh()">Try again</button></main></template>
